import{_ as t,o,c as s,ag as a}from"./chunks/framework.BIas3y6W.js";const g=JSON.parse('{"title":"Screen Reader and Keyboard Guide","description":"","frontmatter":{"source":"resources/accessibility.md"},"headers":[],"relativePath":"resources/accessibility.md","filePath":"resources/accessibility.md"}'),r={name:"resources/accessibility.md"};function n(i,e,d,l,h,c){return o(),s("div",null,[...e[0]||(e[0]=[a('<h1 id="screen-reader-and-keyboard-guide" tabindex="-1">Screen Reader and Keyboard Guide <a class="header-anchor" href="#screen-reader-and-keyboard-guide" aria-label="Permalink to &quot;Screen Reader and Keyboard Guide&quot;">​</a></h1><blockquote><p>How to use the course&#39;s tools with a screen reader or the keyboard alone, and how the course handles timed builds, read-aloud activities and video. Also useful if you use zoom, voice control or captions. If something in the course doesn&#39;t work with your setup, tell your instructor in week 1, or <a href="https://github.com/Boyu-Zhang-UOI/building-apps-with-ai/issues/new/choose" target="_blank" rel="noreferrer">open an issue</a>. It&#39;s a course problem, not yours.</p></blockquote><p><strong>On this page:</strong> <a href="#before-you-start">Before you start</a> · <a href="#chat-assistants">Chat assistants</a> · <a href="#github-on-the-web">GitHub</a> · <a href="#githubdev-and-vs-code-in-a-codespace">github.dev and Codespaces</a> · <a href="#browser-devtools">DevTools</a> · <a href="#timed-builds-read-aloud-activities-and-video">Timed builds, read-aloud activities and video</a> · <a href="#asking-for-accommodations">Accommodations</a> · <a href="#making-your-own-pages-accessible">Your own pages</a></p><hr><h2 id="before-you-start" tabindex="-1">Before you start <a class="header-anchor" href="#before-you-start" aria-label="Permalink to &quot;Before you start&quot;">​</a></h2><ul><li><strong>Use the screen reader and browser you know.</strong> Every course tool runs in a web browser, so a current Chrome, Edge or Firefox works well with NVDA or JAWS on Windows, Safari or Chrome with VoiceOver on a Mac, and ChromeVox on a Chromebook.</li><li><strong>Find commands by name, not by icon.</strong> When a step says &quot;click the icon&quot;, you can almost always search for the command instead: the <strong>Command Palette</strong> in VS Code, <code>?</code> on GitHub, the <strong>Command Menu</strong> in DevTools. Each is covered below.</li><li><strong>Every course page is plain text.</strong> Slides are Markdown files (<code>slides.md</code> in each week) that you can read directly. Diagrams have text versions: the <a href="./safe-loop.html#the-six-steps">Safe Loop</a> is a numbered list, and the <a href="./web-basics.html#the-trust-boundary">trust boundary</a> is a set of lists. AI-use labels always include words: 🟢 AI on, 🟡 AI limited, 🔴 AI off.</li><li><strong>Shortcuts are given for Windows (which usually also work on Linux and ChromeOS) and Mac,</strong> with Linux listed separately where it differs. Menus and shortcuts move. If one doesn&#39;t work, search the tool&#39;s help for &quot;keyboard shortcuts&quot;.</li></ul><h2 id="chat-assistants" tabindex="-1">Chat assistants <a class="header-anchor" href="#chat-assistants" aria-label="Permalink to &quot;Chat assistants&quot;">​</a></h2><p>You use a chat assistant most in weeks 1–6. Chat assistants change their interfaces often, so these are approaches rather than exact keys.</p><ul><li><p><strong>Wait for the reply to finish</strong> before reading it. Some screen readers announce a streaming reply in pieces. Then jump to the last reply by heading or by landmark. Code blocks usually have a <strong>Copy</strong> button right after them.</p></li><li><p><strong>Live previews are hard to explore.</strong> The preview panel (Gemini&#39;s Canvas, Claude&#39;s Artifacts) runs your page inside a frame that some screen readers handle badly, and some previews don&#39;t let you type. Copy the code into a file and open it in its own browser tab instead, using the week 1 lab&#39;s <a href="./../weeks/01-hello-vibe-coding/lab.html#no-preview-run-it-yourself">No preview? Run it yourself</a>. Or publish it on GitHub Pages and test the live page.</p></li><li><p><strong>Ask the assistant for text descriptions.</strong> These prompts help:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Describe the page you just made, element by element, in reading order.</span></span>\n<span class="line"><span>List every button, link and input box, with its visible label and its accessible name.</span></span>\n<span class="line"><span>Check the page for accessibility problems: missing labels or alt text, low contrast, headings out of order, anything a keyboard can&#39;t reach. List them; don&#39;t fix anything yet.</span></span></code></pre></div></li><li><p><strong>Habit 2, &quot;show, don&#39;t describe&quot;, doesn&#39;t need a drawing.</strong> A structured outline (&quot;header with my name; three project cards in a row; a contact link at the bottom&quot;) or a link to a page you like counts as a reference.</p></li><li><p><strong>If your chat tool doesn&#39;t work with your setup,</strong> switch to another one from the chat-assistant row of <a href="./../TOOLS.html">Tool Handout</a>. The course prompts work unchanged.</p></li></ul><h2 id="github-on-the-web" tabindex="-1">GitHub on the web <a class="header-anchor" href="#github-on-the-web" aria-label="Permalink to &quot;GitHub on the web&quot;">​</a></h2><ul><li><strong>Press <code>?</code></strong> on any GitHub page to hear or see its keyboard shortcuts.</li><li><strong>Useful shortcuts:</strong> <code>s</code> or <code>/</code> to search, <code>t</code> to find a file in a repository, <code>.</code> to open the repository in <a href="#githubdev-and-vs-code-in-a-codespace">github.dev</a>, <code>g</code> then <code>c</code> for the Code tab, <code>g</code> then <code>p</code> for Pull requests.</li><li><strong>Single-key shortcuts can clash with your screen reader&#39;s quick keys.</strong> GitHub lets you turn character-key shortcuts off in your account&#39;s accessibility settings. Menus move; search GitHub&#39;s docs for &quot;keyboard shortcuts settings&quot; if you can&#39;t find it.</li><li><strong>Pull requests (weeks 12–14):</strong> in the <strong>Files changed</strong> tab, choose the unified (one-column) view, which reads more simply than split view. To get a whole pull request&#39;s diff as plain text, add <code>.diff</code> to the end of its address, as in <code>https://github.com/[username]/[repo]/pull/1.diff</code>.</li><li><strong>Edit files in github.dev</strong> (press <code>.</code>) rather than in the web page&#39;s own editor: github.dev has all the VS Code features below.</li></ul><h2 id="githubdev-and-vs-code-in-a-codespace" tabindex="-1">github.dev and VS Code in a Codespace <a class="header-anchor" href="#githubdev-and-vs-code-in-a-codespace" aria-label="Permalink to &quot;github.dev and VS Code in a Codespace&quot;">​</a></h2><p>github.dev (weeks 2–5) and a Codespace (weeks 6–16) are both VS Code running in your browser, so the same features work in both.</p><table tabindex="0"><thead><tr><th>To do this</th><th>Windows</th><th>Linux</th><th>Mac</th></tr></thead><tbody><tr><td>Run any command by name (the <strong>Command Palette</strong>)</td><td><strong>Ctrl+Shift+P</strong> or <strong>F1</strong></td><td><strong>Ctrl+Shift+P</strong> or <strong>F1</strong></td><td><strong>Cmd+Shift+P</strong> or <strong>F1</strong></td></tr><tr><td>Get help for the part you&#39;re in (<strong>Accessibility Help</strong>)</td><td><strong>Alt+F1</strong></td><td><strong>Shift+Alt+F1</strong></td><td><strong>Option+F1</strong></td></tr><tr><td>Read the current item as plain text (<strong>Accessible View</strong>): Copilot Chat replies, hovers, suggestions, notifications, terminal output</td><td><strong>Alt+F2</strong></td><td><strong>Shift+Alt+F2</strong></td><td><strong>Option+F2</strong></td></tr><tr><td>Switch screen reader optimized mode on or off</td><td>Command Palette: <em>Toggle Screen Reader Accessibility Mode</em></td><td>Same</td><td>Same</td></tr><tr><td>Move between the editor, side bar, panel and status bar</td><td><strong>F6</strong> / <strong>Shift+F6</strong></td><td><strong>F6</strong> / <strong>Shift+F6</strong></td><td><strong>F6</strong> / <strong>Shift+F6</strong></td></tr><tr><td>Make <strong>Tab</strong> move focus instead of typing a tab (toggle)</td><td><strong>Ctrl+M</strong></td><td><strong>Ctrl+M</strong></td><td><strong>Ctrl+Shift+M</strong></td></tr><tr><td>Explorer (files)</td><td><strong>Ctrl+Shift+E</strong></td><td><strong>Ctrl+Shift+E</strong></td><td><strong>Cmd+Shift+E</strong></td></tr><tr><td>Source Control (commits and diffs)</td><td><strong>Ctrl+Shift+G</strong></td><td><strong>Ctrl+Shift+G</strong></td><td><strong>Ctrl+Shift+G</strong></td></tr><tr><td>Terminal</td><td><strong>Ctrl+`</strong> (backtick)</td><td><strong>Ctrl+`</strong></td><td><strong>Ctrl+`</strong></td></tr><tr><td>Go to a line number (from an error message)</td><td><strong>Ctrl+G</strong></td><td><strong>Ctrl+G</strong></td><td><strong>Ctrl+G</strong></td></tr><tr><td>Next error or warning</td><td><strong>F8</strong></td><td><strong>F8</strong></td><td><strong>F8</strong></td></tr><tr><td>Step through a diff line by line (<strong>Accessible Diff Viewer</strong>)</td><td><strong>F7</strong> / <strong>Shift+F7</strong> in a diff</td><td>Same</td><td>Same</td></tr></tbody></table><p>On a Chromebook, try the Windows keys first; if one doesn&#39;t work, run the command by name from the Command Palette. Shortcuts come from <a href="https://code.visualstudio.com/docs/configure/accessibility/accessibility" target="_blank" rel="noreferrer">VS Code&#39;s accessibility documentation</a>, which has the full list.</p><p><strong>Tips:</strong></p><ul><li><strong>Screen reader mode</strong> is usually switched on automatically when VS Code detects a screen reader. If it isn&#39;t, run <em>Toggle Screen Reader Accessibility Mode</em> from the Command Palette. Accessibility Help in the editor tells you whether it&#39;s on.</li><li><strong>In a browser, some shortcuts belong to the browser</strong> (such as closing or opening tabs). If a shortcut does the wrong thing, open the Command Palette and type the command&#39;s name instead.</li><li><strong>Copilot Chat:</strong> open the Command Palette, type <code>chat</code>, and choose the command that opens the Chat view. After a reply arrives, open the Accessible View (<strong>Alt+F2</strong> on Windows) to read it line by line and copy code.</li><li><strong>Copilot&#39;s grey suggestions</strong> (completions) can be read with the Accessible View. If they get in your way, turn them off and use Chat only (<a href="./../setup/codespaces.html#turn-copilot-off-for-ai-off-activities">how</a>); that&#39;s the same setting AI-off activities use.</li><li><strong>Sounds for errors and events:</strong> VS Code can play a sound for an error line, a warning, a finished task and more. Run <em>Help: List Signal Sounds</em> from the Command Palette to choose which.</li><li><strong>Long terminal output</strong> (<code>npm test</code>, error logs): with the terminal focused, open the Accessible View to read it line by line. Or save it to a file and open that: <code>npm test &gt; test-output.txt 2&gt;&amp;1</code>. Don&#39;t commit that file.</li><li><strong>git&#39;s pager:</strong> <code>git log</code> and <code>git diff</code> open a scrolling viewer that some screen readers handle badly. Add <code>--no-pager</code>, as in <code>git --no-pager log --oneline</code>, to print the output straight into the terminal.</li><li><strong>Prefer a desktop app?</strong> A Codespace can also be opened in the VS Code desktop app, which some screen-reader users find smoother; the Codespace still runs in the cloud. Look for the option to open it in VS Code Desktop (menus move).</li></ul><h2 id="browser-devtools" tabindex="-1">Browser DevTools <a class="header-anchor" href="#browser-devtools" aria-label="Permalink to &quot;Browser DevTools&quot;">​</a></h2><p>You use DevTools from week 1 and constantly from week 7 (<a href="./web-basics.html#a-short-devtools-tour">tour</a>).</p><table tabindex="0"><thead><tr><th>To do this</th><th>Windows, Linux, ChromeOS</th><th>Mac</th></tr></thead><tbody><tr><td>Open DevTools</td><td><strong>F12</strong> or <strong>Ctrl+Shift+I</strong></td><td><strong>Cmd+Option+I</strong></td></tr><tr><td>Open straight to the Console (Chrome, Edge)</td><td><strong>Ctrl+Shift+J</strong></td><td><strong>Cmd+Option+J</strong></td></tr><tr><td>Open straight to the Console (Firefox)</td><td><strong>Ctrl+Shift+K</strong></td><td><strong>Cmd+Option+K</strong></td></tr><tr><td>Run any DevTools command by name (Chrome, Edge: the <strong>Command Menu</strong>)</td><td><strong>Ctrl+Shift+P</strong> with DevTools focused</td><td><strong>Cmd+Shift+P</strong></td></tr><tr><td>Switch to the next or previous panel (Chrome, Edge)</td><td><strong>Ctrl+]</strong> / <strong>Ctrl+[</strong></td><td><strong>Cmd+]</strong> / <strong>Cmd+[</strong></td></tr></tbody></table><ul><li><strong>Command Menu</strong> is the quickest way around: type &quot;Console&quot;, &quot;Network&quot;, &quot;Application&quot; or &quot;Lighthouse&quot; and press Enter.</li><li><strong>Errors without DevTools:</strong> in the starters from week 9 on, server errors are written as plain text in the terminal where <code>npm run dev</code> runs. To see what your server returns, you can use <code>curl</code> in the terminal instead of the Network panel (<a href="./troubleshooting.html#what-the-starters-messages-mean">how</a>).</li><li><strong>Check what your screen reader will announce:</strong> in Chrome or Edge, the <strong>Accessibility</strong> pane under Elements shows each element&#39;s role and accessible name, and the <strong>Lighthouse</strong> panel runs an accessibility audit that lists problems as text. Firefox has an <strong>Accessibility Inspector</strong>. Chrome&#39;s own DevTools documentation has a page on using DevTools with assistive technology.</li></ul><h2 id="timed-builds-read-aloud-activities-and-video" tabindex="-1">Timed builds, read-aloud activities and video <a class="header-anchor" href="#timed-builds-read-aloud-activities-and-video" aria-label="Permalink to &quot;Timed builds, read-aloud activities and video&quot;">​</a></h2><p>These adjustments are open to <strong>everyone</strong>, with or without an accommodation letter.</p><h3 id="timed-builds" tabindex="-1">Timed builds <a class="header-anchor" href="#timed-builds" aria-label="Permalink to &quot;Timed builds&quot;">​</a></h3><p>The course&#39;s timed activities each fit inside one 75-minute studio: the <strong>Game in an Hour</strong> (week 3), the Debug Clinic (week 7), Be the Agent (week 11), the RLS Attack Lab (week 13) and the AI-off maintenance task (week 14). Timed parts are <strong>graded on effort and save points, not speed</strong>, and anyone may do them untimed (<a href="./../assessment/#accommodations">assessment</a>). If you need extra time, tell your instructor in week 1, so it can be planned around that studio instead of cut from the activity. Pick a game from the <a href="./../weeks/03-prompting-and-save-points/game-menu.html">game menu</a> that suits your setup: turn-based games with keyboard controls and text output (a guessing game, a quiz, a typing test) are much easier to test with a screen reader than fast action games. Ask the AI to announce changes, such as the score, in a status message that screen readers read out (an <code>aria-live</code> region).</p><h3 id="read-aloud-activities" tabindex="-1">Read-aloud activities <a class="header-anchor" href="#read-aloud-activities" aria-label="Permalink to &quot;Read-aloud activities&quot;">​</a></h3><ul><li><strong>Be the Agent</strong> (week 11) normally has the Model and the Harness talk aloud. You can run it entirely in typed messages instead, in a shared chat or document. The kit&#39;s task and tool cards are Markdown files you can zoom or read with a screen reader. Working alone, use the <a href="./self-paced.html#working-alone-every-pair-activity">solo version</a>.</li><li><strong>Peer explanation swaps, pitches and debriefs:</strong> typed instead of spoken is fine. Ask for a quieter corner if the room is noisy.</li><li><strong>Questions after your final presentation,</strong> and any &quot;explain it or redo it&quot; conversation: written answers or extra time are fine (<a href="./../assessment/#accommodations">accommodations</a>). Your instructor can read code aloud if that helps.</li></ul><h3 id="video" tabindex="-1">Video <a class="header-anchor" href="#video" aria-label="Permalink to &quot;Video&quot;">​</a></h3><ul><li><strong>Your final presentation</strong> (week 16) is live. If presenting live is a barrier, a pre-recorded demo with captions or on-screen text and live questions, or a written script with screenshots, counts the same (<a href="./../assessment/#accommodations">accommodations</a>). Any backup recording you make needs captions or a transcript.</li><li><strong>Record somewhere quiet.</strong> If the studio is noisy, record at home later.</li><li><strong>Recorded concept talks</strong> are posted on Canvas. If one has no captions, ask. Each talk&#39;s <code>slides.md</code> is the same content in text.</li><li><strong>Recording studios yourself</strong> is allowed with the instructor&#39;s consent or as an approved CDAR accommodation, and in either case you tell the instructor first (<a href="./../assessment/#privacy-of-your-work">assessment guide</a>).</li></ul><h2 id="asking-for-accommodations" tabindex="-1">Asking for accommodations <a class="header-anchor" href="#asking-for-accommodations" aria-label="Permalink to &quot;Asking for accommodations&quot;">​</a></h2><p>If you believe you need disability-related academic adjustments, contact the University of Idaho&#39;s <strong><a href="https://www.uidaho.edu/student-resources/disability-accessibility-resources" target="_blank" rel="noreferrer">Center for Disability Access and Resources (CDAR)</a></strong>. How the course handles accommodations is set out in the <a href="./../assessment/#accommodations">assessment guide</a>.</p><ul><li><strong>Contact CDAR early,</strong> ideally before the course starts or in week 1. A current CDAR accommodation letter is needed for adjustments beyond those open to everyone, and adjustments are not retroactive.</li><li><strong>Tell your instructor in week 1</strong> what you use (a screen reader, captions, voice control, extra time) so demos, labs and the final presentation can be set up for it. You don&#39;t have to say why.</li><li><strong>Everything on this page is open to all students</strong> without a letter: untimed timed builds, typed answers, the video alternatives, the tool approaches above. The full list is in <a href="./../assessment/#accommodations">Assessment: Accommodations</a>.</li></ul><p>Following the course on your own? Use any of these adjustments freely; see the <a href="./self-paced.html">self-paced path</a>.</p><h2 id="making-your-own-pages-accessible" tabindex="-1">Making your own pages accessible <a class="header-anchor" href="#making-your-own-pages-accessible" aria-label="Permalink to &quot;Making your own pages accessible&quot;">​</a></h2><p>The same skills make your own projects usable by everyone. Week 2 has an accessibility check of your home page, and week 15 has a full polish pass (<a href="./../weeks/15-ship-it/polish-checklist.html">polish checklist</a>). The quick version:</p><ol><li><strong>Keyboard test:</strong> put the mouse away and press <strong>Tab</strong> through the page. You should reach and use every button and field with Tab, Enter and Space, and always see where you are.</li><li><strong>Screen reader test:</strong> listen to the page from the top. Do the headings make an outline? Does every image have <a href="./glossary.html#alt-text">alt text</a>, and every field a label?</li><li><strong>Audit:</strong> run DevTools&#39; <strong>Lighthouse</strong> accessibility audit and fix what it lists, most serious first.</li></ol><p>More: <a href="./glossary.html#accessibility">accessibility in the glossary</a>.</p>',37)])])}const m=t(r,[["render",n]]);export{g as __pageData,m as default};
